import React from 'react';
import './App.css'; // Assure-toi que ce fichier est importé

function App() {
  return (
    <div className="bg-gray-100 p-6 rounded-md shadow-md">
      <h1 className="text-2xl font-bold text-blue-500 mb-4">Bienvenue avec Tailwind CSS !</h1>
      <p className="text-gray-700">Ceci est un test pour vérifier que Tailwind fonctionne correctement.</p>
      <button className="bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded">
        Tester le bouton
      </button>
    </div>
  );
}

export default App;
